import re,glob,yaml,os,collections
files=sorted(glob.glob("30_Library/100_zettelkasten/*.md"))
rows=[]
for p in files:
    t=open(p).read()
    m=re.match(r"^---\n(.*?)\n---\n(.*)$",t,re.S)
    if not m: rows.append(dict(p=p,fm=None,body=t)); continue
    try: fm=yaml.safe_load(m.group(1)) or {}
    except: fm={"_yaml_error":1}
    rows.append(dict(p=p,fm=fm,body=m.group(2)))
N=len(rows)
print("notes:",N)
def title(r): return os.path.basename(r['p'])[:-3]
# type distribution
c=collections.Counter(str((r['fm'] or {}).get('type')) for r in rows); print("type:",c.most_common(12))
# body opening style
def bodystyle(b):
    b=b.strip()
    first=b.split("\n",1)[0] if b else ""
    hs=re.findall(r"^(#{1,6}) (.+)$",b,re.M)
    heads=[h[1].strip() for h in hs]
    lv=lambda n: sum(1 for h in hs if len(h[0])==n)
    return first,heads,lv
sig=collections.Counter()
ex={}
for r in rows:
    b=r['body']; first,heads,lv=bodystyle(b)
    s=[]
    s.append("H2title" if first.startswith("## ") else "H3title" if first.startswith("### ") else "H1title" if first.startswith("# ") else "Summary:" if first.startswith("Summary:") else "prose")
    hn=" ".join(h.lower() for h in heads)
    if "scope & conditions" in hn: s.append("scope")
    if "evidence" in hn: s.append("evidence")
    if "implications" in hn: s.append("implications")
    if "steelman" in hn: s.append("steelman")
    if "open questions" in hn: s.append("openq")
    if "knowledge graph" in hn: s.append("KG")
    if "related" in hn: s.append("related")
    if "tensions" in hn: s.append("tensions")
    if "see also" in hn: s.append("seealso")
    if re.search(r"^Details:",b,re.M): s.append("Details:")
    if re.search(r"^Links:",b,re.M): s.append("Links:")
    k=" ".join(s); sig[k]+=1; ex.setdefault(k,title(r))
print("\nBODY STYLE SIGNATURES (top 18):")
for k,n in sig.most_common(18): print(f"{n:4d}  {k}   e.g. {ex[k][:55]}")
# frontmatter completeness
def has(r,k): return r['fm'] is not None and k in r['fm'] and r['fm'][k] not in (None,"",[])
keys=["type","conformant","proposition","epistemic_status","definition","tags","prodos","created","modified","status","upstream"]
print("\nFRONTMATTER presence:")
for k in keys: print(f"  {k:18s}{sum(1 for r in rows if has(r,k)):4d} / {N}")
print("  no frontmatter:",sum(1 for r in rows if r['fm'] is None))
print("  conformant false:",sum(1 for r in rows if r['fm'] and r['fm'].get('conformant') is False))
print("  empty tags:",sum(1 for r in rows if r['fm'] is not None and not r['fm'].get('tags')))
# title styles
ts=collections.Counter()
for r in rows:
    t=title(r)
    if re.match(r"^\d{4}-\d{2}-\d{2}-",t): ts["date-slug"]+=1
    elif t.startswith(("Claim - ","Evidence - ","Q — ","Question - ","SoT - ","MOC - ","HEAD - ")): ts["prefix:"+t.split(" ")[0]]+=1
    elif len(t.split())>=6: ts["sentence-like (6+ words)"]+=1
    elif len(t.split())<=3: ts["short label (<=3 words)"]+=1
    else: ts["4-5 words"]+=1
print("\nTITLE styles:",ts.most_common())
# wikilink style: typed edges inline vs section
print("\nhas typed edge line:",sum(1 for r in rows if re.search(r"\[(extends|synthesizes|implements|contradicts|supports|depends_on)::",r['body'])))
print("has 'rel::' legacy:",sum(1 for r in rows if "rel::" in r['body']))
print("no outbound wikilink:",sum(1 for r in rows if not re.search(r"\[\[",r['body'])))
print("frontmatter-only link fields (evidence_links etc):",sum(1 for r in rows if has(r,'evidence_links')))
